#!/usr/bin/env bash
# Regenerates src/pcan/bindings.rs from the vendored PCANBasic.h.
#
# Only needed when include/PCANBasic.h is updated. Requires `bindgen-cli`
# (`cargo install bindgen-cli`) and libclang.
#
# The header only uses fixed-width integer types and has no platform
# conditionals, so the generated file is valid for all supported targets.
# Function declarations are skipped because the library is loaded at runtime.
set -euo pipefail
cd "$(dirname "$0")/.."

bindgen include/wrapper.h \
    --blocklist-function '.*' \
    --allowlist-var 'PCAN_.*' \
    --allowlist-type 'TPCAN.*' \
    --raw-line '// Generated by scripts/gen-pcan-bindings.sh - do not edit by hand.' \
    --output src/pcan/bindings.rs \
    -- -Wno-ignored-attributes

rustfmt --edition 2021 src/pcan/bindings.rs
